    d = vws.cell(row=row, column=4).value

    c_on = is_num(c) and c > 1
    d_on = is_num(d) and d > 1

    if c_on and not d_on:
        ref = formula_c_ref(row) or default_c_ref(row)
        val = ref_value(ref)
    elif d_on and not c_on:
        ref = d_ref_for(formula_c_ref(row), row)
        val = ref_value(ref)
    else:
        val = None

